frappe.ui.form.on('Relieving Letter', {
    employee_id: function(frm) {
        frappe.call({
            method: 'frappe.client.get',
            args: {
                doctype: 'Employee',
                name: frm.doc.employee_id,
                filters: {
                    fields: ['employee_name', 'designation', 'date_of_joining', 'relieving_date']
                }
            },
            callback: function(response) {
                var data = response.message;
                if (data) {
                    frm.set_value('employee_name', data.employee_name);
                    frm.set_value('designation', data.designation);
                    frm.set_value('date_of_joining', data.date_of_joining);
                    frm.set_value('relieving_date', data.relieving_date);
                    frm.set_value('resignation_letter_date', data.resignation_letter_date);
                }
            }
        });
    }
});

frappe.ui.form.on('Relieving Letter', {
    mail_template: function(frm) {
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Letter Template',
                filters: { name: frm.doc.mail_template },
                fieldname: 'content'
            },
            callback: function(response) {
                var data = response.message;
                if (data && data.content) {
                    frm.set_value('mail', data.content);
                    frm.set_value('modified_mail', data.content);
                }
            }
        });
    }
});
frappe.ui.form.on('Relieving Letter', {
    mail_template: function(frm) {
        var mailTemplate = frm.doc.mail_template;

        if (mailTemplate) {
            frappe.model.with_doc('Letter Template', mailTemplate, function() {
                var letterTemplate = frappe.model.get_doc('Letter Template', mailTemplate);
                var content = replaceFieldValues(letterTemplate.content, frm.doc);

                frm.set_value('modified_mail', content);
            });
        }
    },
    before_save: function(frm) {
        var modifiedContent = frm.doc.modified_mail;
        frm.set_value('mail', modifiedContent);
    }
});

function replaceFieldValues(content, doc) {
    var fieldNames = ['employee_name', 'employee_id', 'date_of_joining', 'designation', 'relieving_date','resignation_letter_date'];

    fieldNames.forEach(function(fieldName) {
        var fieldValue = doc[fieldName];
        var regex = new RegExp('{{' + fieldName + '}}', 'g');
        content = content.replace(regex, fieldValue);
    });

    return content;
}



