frappe.ui.form.on('Salary Slip', {
    employee: function(frm) {
        var employee = frm.doc.employee;

        if (!employee) {
            frappe.msgprint(__('Please select an employee.'));
            return;
        }

        // Fetch the base field value from the Salary Structure Assignment
        frappe.db.get_list('Salary Structure Assignment', {
            filters: { employee: employee },
            fields: ['base'],
            limit: 1
        }).then(function(response) {
            if (response && response.length > 0) {
                // Set the fetched value to the hour_rate field in Salary Slip
                frm.set_value('hour_rate', response[0].base);
                frm.refresh_field('hour_rate');
            } else {
                frappe.msgprint(__('No Salary Structure Assignment found for the selected employee.'));
            }
        }).catch(function(err) {
            console.error(err);
        });
    }
});

frappe.ui.form.on("Employee", {
    before_save: function(frm) {
        // Calculation of number of days
        var today_date = frappe.datetime.nowdate();
        var joining_date = frm.doc.date_of_joining;
        var number_of_days = frappe.datetime.get_day_diff(today_date, joining_date);
        frm.doc.nos_of_days = number_of_days;
        // Calculation of PO or PM
        frm.doc.new_po_or_pm = frm.doc.po_per_month_;
        // Calculation of CTC or Salary PM
        frm.doc.new_ctc_or_salary_pm = frm.doc.new_salary_per_month;
        // Calculation of Salary
        frm.doc.new_salary = (frm.doc.new_ctc_or_salary_pm * 12 / 365 * frm.doc.nos_of_days);
        // Calculation of Base
        frm.doc.new_base = (frm.doc.new_po_or_pm * 12 / 365 * frm.doc.nos_of_days);
        // Calculation of GST
        frm.doc.gst = (frm.doc.new_base * 18 / 100);
        // Calculation of Total
        frm.doc.new_total = (frm.doc.new_base + frm.doc.gst);
        // Calculation of TDS
        frm.doc.new_tds = (frm.doc.new_base * 10 / 100);
        // Calculation of AF Tax
        frm.doc.new_af_tax = (frm.doc.new_total - frm.doc.new_tds);
        // Calculation of Amt in Bank or Profit
        frm.doc.new_amt_in_bank_or_profit = (frm.doc.new_af_tax - frm.doc.new_salary);
        // Calculation of Fixed Cost Margin or Net Profit
        frm.doc.new_fixed_cost_margin_or_net_profit = (frm.doc.new_amt_in_bank_or_profit - (frm.doc.new_amt_in_bank_or_profit * 10 / 100));
        // Calculation of 40 Percentage on Base
        frm.doc.new_percentage_on_base = (frm.doc.new_base * 40 / 100);
        // Calculation of Below 40 Percentage
        frm.doc.new_below_40_percentage = (frm.doc.new_fixed_cost_margin_or_net_profit - frm.doc.new_percentage_on_base);
        // Calculation of Percentage
        frm.doc.new_percentage = (frm.doc.new_fixed_cost_margin_or_net_profit / frm.doc.new_base * 100);
    }
});


