function toggleMandatoryFields(frm) {
    var customFte = frm.doc.custom_fte;

    // Define the fields you want to toggle mandatory requirement for
    var fieldsToMakeMandatory = [
        'client_account_manager',
        'new_salary_per_month',
        'new_billing',
        'person_to_be_contacted',
        'emergency_phone_number',
        'payroll_cost_center',
        'bank_name',
        'bank_ac_no',
        'ifsc_code',
        'company_email',
        'pan_number'
    ];

    // Set mandatory requirement for specified fields based on custom_fte
    fieldsToMakeMandatory.forEach(function(field) {
        frm.toggle_reqd(field, !customFte); // Fields are mandatory when custom_fte is unchecked
    });
}
frappe.ui.form.on('Employee', {
    refresh: function(frm) {
        // Check if the current user has the 'System Manager' role
        if (frappe.user.has_role('System Manager')) {
            // Add custom button to handle enabling/disabling user
            frm.add_custom_button(__('Update User Account Status'), function() {
                if (frm.doc.status === 'Left' && frm.doc.user_id) {
                    frappe.db.set_value('User', frm.doc.user_id, 'enabled', 0)
                        .then(function(response) {
                            if (response && !response.exc) {
                                frappe.msgprint(__('The linked user account has been disabled.'));
                            } else {
                                frappe.msgprint(__('There was an issue disabling the linked user account.'));
                            }
                        });
                } 
                else if (frm.doc.status === 'Active' && frm.doc.user_id) {
                    frappe.db.set_value('User', frm.doc.user_id, 'enabled', 1)
                        .then(function(response) {
                            if (response && !response.exc) {
                                frappe.msgprint(__('The linked user account has been enabled.'));
                            } else {
                                frappe.msgprint(__('There was an issue enabling the linked user account.'));
                            }
                        });
                } else {
                    frappe.msgprint(__('Please ensure the status is set to either "Active" or "Left" and the user ID is present.'));
                }
            });
        }
    }
});



frappe.ui.form.on('Employee', {
    validate: function(frm) {
        // Check if ifsc_code field is filled
        if (frm.doc.ifsc_code) {
            // Regular expression to match exactly 11 alphanumeric characters
            const ifsc_regex = /^[A-Za-z0-9]{11}$/;
            
            // Validate the ifsc_code
            if (!ifsc_regex.test(frm.doc.ifsc_code)) {
                // If not valid, throw an error and prevent form submission
                frappe.msgprint(__('IFSC Code must be exactly 11 alphanumeric characters.'));
                frappe.validated = false;
            }
        }
    }
});
frappe.ui.form.on('Employee', {
    refresh: function(frm) {
        // Check if the user_id field is filled
        if (frm.doc.user_id) {
            // Call a server-side function to check if the record is already shared
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "DocShare",  // DocShare table stores shared records
                    filters: {
                        share_name: frm.doc.name,   // The employee record name
                        user: frm.doc.user_id       // The user to check
                    },
                    fields: ["name"]
                },
                callback: function(response) {
                    const shared_records = response.message;

                    // If the record is not already shared, proceed to share it
                    if (shared_records.length === 0) {
                        frappe.call({
                            method: "frappe.share.add",
                            args: {
                                doctype: "Employee",           // Doctype to share
                                name: frm.doc.name,             // Employee ID (record name)
                                user: frm.doc.user_id,          // User ID (email) to share with
                                read: 1,                        // Set read permission
                                write: 0,                       // Set write permission
                                share: 0                        // Set share permission
                            },
                            callback: function(response) {
                                if (!response.exc) {
                                    frappe.msgprint(__('Employee record has been successfully shared with user: ' + frm.doc.user_id));
                                } else {
                                    frappe.msgprint(__('Failed to share the employee record. Please check if the user exists.'));
                                }
                            }
                        });
                    }
                }
            });
        }
    }
});
