function shareJobRecords(frm) {
    // Check if both job_applicants and job_offer fields exist
    if (!frm.doc.job_applicants && !frm.doc.job_offer) {
        frappe.msgprint(__('No Job Applicant or Job Offer records to share.'));
        return;
    }

    const user = frm.doc.user_id; // Get user from user_id field

    const sharePromises = [];

    // Share Job Applicant record
    if (frm.doc.job_applicants) {
        sharePromises.push(
            frappe.call({
                method: 'frappe.share.add',
                args: {
                    doctype: 'Job Applicant',
                    name: frm.doc.job_applicants,
                    user: user,
                    read: 1,
                    write: 0,
                    share: 0
                }
            })
        );
    }

    // Share Job Offer record
    if (frm.doc.job_offer) {
        sharePromises.push(
            frappe.call({
                method: 'frappe.share.add',
                args: {
                    doctype: 'Job Offer',
                    name: frm.doc.job_offer,
                    user: user,
                    read: 1,
                    write: 0,
                    share: 0
                }
            })
        );
    }

    // Handle all promises and provide feedback
    Promise.all(sharePromises)
        .then(() => {
            frappe.msgprint(__('Successfully shared the Job Applicant and Job Offer records.'));
        })
        .catch((error) => {
            console.error(error);
            frappe.msgprint(__('There was an error sharing the records. Please check the logs.'));
        });
}

frappe.ui.form.on("Employee", {
    refresh: function (frm) {
        if (frm.doc.pan_number) {
            setTimeout(() => {
                set_pan_status(frm.fields_dict["pan_number"]);
            }, 500);
        }

        // Attach event when PAN number is changed
        frm.fields_dict["pan_number"].$input.on("change", function () {
            set_pan_status(frm.fields_dict["pan_number"]);
        });
    }
});

async function set_pan_status(field, force_update = null) {
    const pan = field.value;
    field.set_description(""); // Clear previous status

    if (!pan || pan.length !== 10) return;

    try {
        let { message } = await frappe.call({
            method: "india_compliance.gst_india.doctype.pan.pan.get_pan_status",
            args: { pan, force_update },
        });

        if (!message) return;

        const [pan_status, datetime] = message;
        const STATUS_COLORS = {
            Valid: "green",
            "Not Linked": "red",
            Invalid: "red",
        };

        const user_date = frappe.datetime.str_to_user(datetime);
        const pretty_date = frappe.datetime.prettyDate(datetime);

        // Status indicator under PAN field
        const pan_desc = $(`
            <div class="d-flex indicator ${STATUS_COLORS[pan_status] || "orange"}">
                Status:&nbsp;<strong>${pan_status}</strong>
                <span class="text-right ml-auto">
                    <span title="${user_date}">
                        ${datetime ? "updated " + pretty_date : ""}
                    </span>
                    <svg class="icon icon-sm refresh-pan" style="cursor: pointer;">
                        <use href="#icon-refresh"></use>
                    </svg>
                </span>
            </div>
        `);

        // Refresh button to manually update PAN status
        pan_desc.find(".refresh-pan").on("click", async function () {
            await set_pan_status(field, true);
        });

        field.set_description(pan_desc);
    } catch (error) {
        console.error("Error fetching PAN status:", error);
    }
}

