        updateTimeLogs(frm);
    },
    custom_end_date: function(frm) {
        populateDates(frm);
        updateTimeLogs(frm);
    },
    refresh: function(frm) {
        colorWeekendRows(frm);
    },
    before_save: function(frm) {
        updateBillingHours(frm);
    }
});

function updateBillingHours(frm) {
    frm.doc.time_logs.forEach(function(time_log) {
        if (time_log.hours === 0) {
            time_log.is_billable = 0;
        } else {
            time_log.is_billable = 1;
        }
    });
}

function populateDates(frm) {
    var start = frm.doc.custom_start_date;
    var end = frm.doc.custom_end_date;
    var dates = [];

    var currentDate = moment(start);

    while (currentDate <= moment(end)) {
        var date = currentDate.format('YYYY-MM-DD');
        var day = currentDate.format('dddd');

        dates.push({ date: date, day: day });

        currentDate.add(1, 'day');
    }

    frm.clear_table('time_logs');

    dates.forEach(function(dateEntry) {
        var childRow = frappe.model.add_child(frm.doc, 'Timesheet Detail', 'time_logs');
        frappe.model.set_value(childRow.doctype, childRow.name, 'custom_day', dateEntry.day);
        frappe.model.set_value(childRow.doctype, childRow.name, 'from_time', dateEntry.date);
        frappe.model.set_value(childRow.doctype, childRow.name, 'to_time', dateEntry.date);
        frappe.model.set_value(childRow.doctype, childRow.name, 'hours', 0); // Set hours to 0
    });

    updateTimeLogs(frm);
    frm.refresh_field('time_logs');
    colorWeekendRows(frm);
}

function updateTimeLogs(frm) {
    frm.doc.time_logs.forEach(function(time_log) {
        if (time_log.custom_day === 'Saturday' || time_log.custom_day === 'Sunday') {
            time_log.hours = 0;
            time_log.custom_status = 'Weekend';
            time_log.billing_hours = 0;
        } else {
            time_log.hours = 0;
            time_log.custom_status = 'Working Day';  // Assuming you want it to be billable on weekdays
            time_log.billing_hours = 0;
        }
    });
}

function colorWeekendRows(frm) {
    frm.fields_dict["time_logs"].grid.wrapper.find('.grid-body .rows .grid-row').each(function(i, item) {
        let d = locals[frm.fields_dict["time_logs"].grid.doctype][$(item).attr('data-name')];
        if (d["custom_status"] === 'Weekend') {
            $(item).find('.grid-static-col').css({ 'background-color': 'grey' });
        }
        else if (d["custom_status"] === 'Leave') {
            $(item).find('.grid-static-col').css({ 'background-color': 'red' });
        }
        else if (d["custom_status"] === 'Holiday') {
            $(item).find('.grid-static-col').css({ 'background-color': 'orange' });
        }
    });
}
