});

function calculate_percentage(frm) {
    let total_fields = 5;
    let filled_fields = 0;

    if (frm.doc.resigned) filled_fields += 1;
    if (frm.doc.resignation_accepted) filled_fields += 1;
    if (frm.doc.relocated__at_work_location) filled_fields += 1;
    if (frm.doc.last_working_date) filled_fields += 1;
    if (frm.doc.bgv_ir_cleared) filled_fields += 1;

    let percentage = (filled_fields / total_fields) * 100;
    frm.set_value('completion_percentage', percentage);
}

function update_response_date(frm) {
    let status = 'Update Pending';

    if (frm.doc.resigned && frm.doc.resignation_accepted && frm.doc.relocated__at_work_location) {
        status = 'Completed';
    } else if (frm.doc.resigned && frm.doc.resignation_accepted && !frm.doc.relocated__at_work_location) {
        status = 'Relocation Pending';
    } else if (frm.doc.resigned && frm.doc.resignation_accepted) {
        status = 'Resignation Accepted';
    } else if (frm.doc.resigned) {
        status = 'Resigned';
    }

    frm.set_value('completion_status', status);
}

frappe.listview_settings['Pre-Onboarding'] = {
    add_fields: ["completion_percentage", "joining_date"],

    formatters: {
        // Formatter for percentage to display a progress bar with color
        completion_percentage: function(value) {
            let color = value === 100 ? 'green' : 'red';
            return `
                <div style="position: relative; width: 100%; height: 8px; background-color: #e0e0e0; border-radius: 4px;">
                    <div style="width: ${value}%; height: 100%; background-color: ${color}; border-radius: 4px;"></div>
                </div>
            `;
        }
    },

    get_indicator: function(doc) {
        
    if (doc.completion_percentage === 100) {
            return [__("Completed"), "green", "completion_percentage"];
        }
        
    if (doc.joining_date) {
        const today = frappe.datetime.get_today();
        const days_left = frappe.datetime.get_diff(doc.joining_date, today);

        let color = "green";
        if (days_left < 0) {
            color = "red";  // Past joining date
        } else if (days_left <= 7) {
            color = "orange";  // Less than a week left
        } else if (days_left <= 30) {
            color = "blue";  // Less than a month left
        }

        // Ensure correct label formatting
        return [__(`${days_left} Days Left`), color, "joining_date"];
    } else {
        return [__("No Joining Date"), "gray", "joining_date"];
    }
}
};
